-- future deadlines 188. Replay: timestamps use now(); run against the post-pass-112 state.

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (970, 'DOC Fellowship - Austrian Academy of Sciences (ÖAW)', 'Austrian Academy of Sciences (ÖAW)', 'Austria', 'Partial Funding', 0, 'One submission window per year: mid-August to 15 September (the 2026 window ran 17 August - 15 September 2026, 23:59 CEST, and is closed; the next window follows in 2027 - no dated future deadline is published yet, so no deadline_date is recorded). Applications go through the ÖAW online form on stipendien.oeaw.ac.at; the fellowship must start within four months of the committee decision.', NULL, 'not_published', NULL, NULL, $j$["PhD"]$j$, $j$["All areas of basic research - doctoral/PhD studies at any university in Austria (a cotutelle agreement between an Austrian and a foreign university is also possible)"]$j$, $j$["Highly qualified doctoral candidates of any nationality who pursue (or are about to start) their doctorate at a university in Austria; no nationality restriction is published"]$j$, NULL, NULL, false, true, $desc$DOC is the doctoral fellowship programme of the Austrian Academy of Sciences (ÖAW): it supports highly qualified doctoral candidates from all areas of basic research so that they can dedicate themselves to writing their dissertation in a concentrated manner and with a clear time frame. The fellowship is granted for 24, 30 or 36 months (the requested period can be shortened for budget reasons; with proof of (child) care obligations or (chronic) illness or disability it can be extended cost-neutrally by up to half of the approved period). The value is set in the ÖAW Fellowship Rates - for approvals in 2026 it is €52,080 per year. That figure is a personnel-costs (super gross) sum: it includes all legally required taxes and non-wage labour costs including the employer's contribution, because a DOC fellowship is taken up either through an employment contract at a university or research institution in Austria (the extent of employment follows the institution's collective agreement; full-time is as a rule not possible) or as a 'new self-employed' (Neue:r Selbständige:r) fellow; it is paid in annual instalments and it is NOT increased during the funding period. On top, a travel allowance of up to €500 per year can be applied for (active conference participation or research stays abroad - a dissertation-related stay abroad of up to 12 months is possible within the fellowship) and a childcare subsidy of up to €1,900 (gross/gross) per year. The gate is timing and track record: you must apply before the start of, or within the first year after the start of, doctoral studies at a university in Austria; the master's degree must be completed at application and no more than two years earlier (reference date 1 July of the submission year, with recognised exceptions up to four years for care obligations, military/civilian service, disability or chronic illness); and at least two of three subject-specific criteria - a published or accepted scientific contribution, academic mobility, and scientific engagement - must already be met. A rejected application may be resubmitted once, and parallel applications to other funders are allowed but must be reported (another ÖAW fellowship programme may not be applied for simultaneously). Submission runs once a year in a mid-August to 15 September window.$desc$, $req$Three formal hurdles, all evidenced in the application: (1) doctoral/PhD studies at a university in Austria - apply before starting (proving you meet the university's admission requirements) or within the first year after enrolment (cut-off = enrolment date; reference 1 July of the submission year); cotutelle with a foreign university is allowed. (2) The master's degree completed in full at the time of application and no more than two years before it (certificate date counts; if the certificate is not yet issued, proof that the thesis is assessed/graded and the final exam passed); extensions to a maximum of four years exist only for (child) care obligations, military/civilian service, disability or (chronic) illness and must be cleared with the ÖAW Department of Fellowships & Awards before applying. (3) Subject-specific minimum qualifications: at least two of - proof of at least one published or accepted scientific contribution (article, book chapter, proceedings, poster, review, preprint...); academic mobility (study/research visits, international co-authorships, a degree abroad, active international conference participation, subject-related internships...); scientific engagement (research projects or third-party funding applications, teaching, organising scientific events, professional societies, science communication...). The proposal must be independently written (AI tools permitted but must be declared; good-scientific-practice guidelines apply), and the DOC statutes govern the details. During the fellowship: additional employment such as teaching is permitted if it serves the programme goal; commencement within four months of the decision; no payment for periods before the actual start. No numeric GPA and no IELTS figure apply, so min_gpa/min_ielts are not recorded.$req$, 'https://stipendien.oeaw.ac.at/en/fellowships/doc', 'https://stipendien.oeaw.ac.at/en/fellowships/doc', 'https://stipendien.oeaw.ac.at/en/fellowships/doc/doc-application', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 19) from the Austrian Academy of Sciences' official fellowship portal fetched the same day - the DOC programme page (doctoral fellowship for highly qualified candidates from all areas of basic research; length 24/30/36 months; next submission deadline 17 August - 15 September 2026, 23:59 CEST; application requirements valid from 2026), the DOC Information page (apply before or within the first year of doctoral studies at a university in Austria; master's completed no more than two years before, reference date 1 July, exceptions to four years for care/service/disability/illness cleared in advance; at least two of three criteria - published/accepted scientific contribution, academic mobility, scientific engagement - with the official example lists; one resubmission possible; parallel applications elsewhere allowed but reportable and no simultaneous other ÖAW programme; stay abroad up to 12 months and cotutelle possible; requested period may be shortened for budget, cost-neutral extension up to half for care/illness/disability; start within four months of decision; travel allowance up to EUR 500/year and childcare subsidy up to EUR 1,900/year; paid in annual instalments to the fellow as 'new self-employed' or to the employing Austrian institution; additional employment such as teaching permitted if it serves the programme goal) and the 'Fellowship Rates 2026' PDF (DOC = EUR 52,080 per year, personnel costs/super gross including taxes, non-wage costs and employer's contribution; employment extent per collective agreement, full-time as a rule not possible; amounts not increased during the funding period). The programme was spotted during cleanup pass 112 (Austria) and is catalogued here as the national doctoral scheme it is. Award stored as 52080 EUR/'year'/'fixed': a single published annual rate for 2026 approvals (rates are adjusted yearly but frozen for each awarded fellowship). deadline_date NULL/'not_published': the 2026 window has closed and only the recurring mid-August-15-September pattern is published; status 'upcoming' ahead of the 2027 window. min_gpa/min_ielts NULL. university_id NULL by design (the fellowship attaches to any Austrian university, not one institution); no university_scholarships row. A dedicated verified source was inserted for the ÖAW DOC page.$note$, NULL, 52080, 'EUR', 'year', 'fixed', NULL, 'Personnel-costs funding of €52,080 per year (super gross: taxes, social contributions and employer share included) for 24, 30 or 36 months - taken up as an Austrian employment contract or as a self-employed fellow; plus up to €500/year travel allowance and up to €1,900/year childcare subsidy', 'Not a tuition waiver: the fellowship funds the candidate''s living/research time as personnel costs (employment or self-employment), not university fees.', 'No programme-level IELTS figure; language requirements follow the host university''s doctoral admission rules.', $j$["Master's degree certificate (degree completed no more than two years before the 1 July reference date of the submission year; or proof the thesis is graded and the final exam passed if the certificate is pending)", "Dissertation project proposal (independently written; AI use must be declared), evaluated under the DOC programme statutes", "Proof that the doctorate is (or will be) pursued at a university in Austria: enrolment within the first year, or evidence of meeting the admission requirements if applying before the start", "Evidence for at least two of the three criteria: published/accepted scientific contribution, academic mobility, scientific engagement", "Recommendation letter of the dissertation supervisor (part of the standard application package referenced on the programme page)"]$j$, NULL, NULL, $json$[{"round": "2026", "submission": "2026-08-17 to 2026-09-15", "status": "closed"}, {"pattern": "Annual: submission mid-August to 15 September via the ÖAW online form; multi-stage expert review; fellowship (24/30/36 months) must start within four months of the committee decision"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (971, 'Ernst Mach Grant - worldwide (OeAD)', 'OeAD - Austria''s Agency for Education and Internationalisation', 'Austria', 'Partial Funding', 0, 'Online application is open NOW for research stays in the Austrian academic year 2027/28 (earliest start September 2027): the window runs from September to 1 December 2026, 23:59 CET - documents arriving after the deadline are not accepted. Formal check first, then expert evaluation; results are expected at the beginning of July 2027. Do not submit at the last moment (automatic completeness checks; technical support only in office hours).', '2026-12-01', 'fixed', NULL, NULL, $j$["PhD", "Postdoc"]$j$, $j$["All disciplines - a 1-9 month research project at an Austrian university (written confirmation of supervision from an Austrian lecturer required; research stays only, never a full degree programme)"]$j$, $j$["All countries except Austria: young researchers based outside Austria - postgraduates pursuing a doctorate abroad, recent graduates/post-docs aiming at an academic career, and post-doc lecturers/researchers at universities outside Austria (not already permanently resident or mainly educated in Austria; no stay in Austria in the six months before taking up the grant)"]$j$, NULL, NULL, false, true, $desc$The Ernst Mach Grant - worldwide is the Austrian federal government's incoming mobility grant, financed by the Federal Ministry of Women, Science and Research and run by the OeAD: it funds a research stay of 1 to 9 months in Austria for young researchers from all disciplines and all countries except Austria. The grant is a monthly rate of €1,300, expressly a supplementary grant - the OeAD itself warns that the rates assume actual living costs in Austria exceed the grant, so own funds are required; the OeAD assists with arranging accommodation (OeAD student housing can be booked, at the holder's own cost) and the compulsory health insurance, and holders travelling from non-European developing countries can additionally receive a travel costs subsidy of up to €1,200 against original invoices. Who may apply is tightly drawn around early-career mobility: postgraduates pursuing a doctoral programme outside Austria; postgraduates and post-docs who want to research in Austria with a view to an academic career and who finished their studies at a university outside Austria recently (after 30 September 2025 in the current call); and post-docs working as lecturers or researchers at a university outside Austria. Applicants must not be older than 35 at the start of the stay, must not be regular students at an Austrian university, must not be permanently resident in Austria or have completed their education mainly in Austria, and must not have lived, studied or done academic work in Austria in the last six months before taking up the grant. Equally important: the grant cannot finance a complete or partial regular degree programme - it is for a visiting research stay supervised by an Austrian academic (a written confirmation of supervision on the OeAD template is mandatory, and that supervisor cannot double as a referee). The current call covers stays in the Austrian academic year 2027/28 (earliest start September 2027; for stays over six months, non-EU applicants are advised to plan a November/December start because of residence-permit processing), with applications from September to 1 December 2026 and results expected at the beginning of July 2027.$desc$, $req$Eligibility in the current call: (a) postgraduates pursuing a doctoral/PhD programme outside Austria; or (b) postgraduates and post-docs seeking research in Austria with a view to an academic career who finished their studies at a university outside Austria after 30 September 2025; or (c) post-docs working as lecturers or researchers at a university outside Austria - in all cases no older than 35 years at the start of the stay, not permanently resident in Austria, not mainly educated in Austria, not regular students at an Austrian university, and with no stay in Austria in the six months before taking up the grant. The stay (1-9 full months, first to last of a month) is a research project only - enrolment as a regular student is not required, but a written confirmation of supervision from an Austrian university lecturer (OeAD template, with date, signature and stamp) is; OeAD does not broker supervisors. Recommendation letters must be on letterhead, dated, signed and stamped, and no older than six months (the supervisor cannot also write one); documents in English need no translation, other languages need the original plus a rough English/German translation (no certified translation); a valid biometric passport must be uploaded; generative AI use must be declared in the application. No TOEFL/IELTS certificate is required, but sufficient English in the subject area is expected and the supervisor must confirm the project can be done in English. Formal invalidity is common (missing information, insufficiently described stay, minimum word counts unmet), and late documents are never accepted. No numeric GPA or IELTS figure is published, so min_gpa/min_ielts are not recorded.$req$, 'https://oead.at/en/study-research-teaching/overview-grants-and-scholarships/ernst-mach-grant', 'https://oead.at/en/study-research-teaching/overview-grants-and-scholarships/ernst-mach-grant', 'https://grants.at/en/', 'annual', 'open', 'verified', 9, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 19) from the OeAD's official pages fetched the same day - the Ernst Mach Grant programme page (named after Ernst Mach; financed by the Federal Ministry of Women, Science and Research; worldwide line: young researchers from all disciplines and countries except Austria; duration 1-9 months; age limit 35; online application September to 1 December) and the call-specific FAQ for the Austrian academic year 2027/28 (eligible groups: postgraduates pursuing a doctorate outside Austria, postgraduates/post-docs who finished their studies outside Austria after 30 September 2025, and post-doc lecturers/researchers outside Austria; not older than 35 at stay start; regular students in Austria, persons permanently resident or mainly educated in Austria not eligible; no Austria stay in the six months before taking up the grant; expressly not for financing a full or partial regular degree; earliest stay September 2027 with November/December start advised for non-EU stays over 6 months; written confirmation of supervision on the OeAD template required and the supervisor cannot also be a referee; recommendation letters on letterhead, dated, signed, stamped, max six months old; no TOEFL needed; translation and passport rules; AI use must be declared; deadline 1 December 2026, 23:59 CET, late documents rejected; formal check then expert evaluation, results expected beginning of July 2027; grant rates assume living costs exceed the grant, own funds required, no possibility to increase the rate). The monthly figure is the one figure OeAD's own pages do not print: the current cycle's grants.at call text as relayed verbatim on Austrian university call pages (e.g. Academy of Fine Arts Vienna, call for the 2026 cycle) and the EU EURAXESS portal states a monthly grant rate of EUR 1,300 plus assistance with accommodation and health insurance, with a travel costs subsidy of max EUR 1,200 for holders travelling from non-European developing countries; older calls paid EUR 1,250 (2024) and EUR 1,150/1,250 (2022), i.e. the rate is revised upward between calls. Reliability 9 rather than 10 for that single relayed (not OeAD-domain) figure; everything else is first-hand from oead.at. Award stored as 1300 EUR/'month'/'fixed' for the 2026 application cycle. deadline_date 2026-12-01 ('fixed') with status 'open': the FAQ confirms the live call for AY 2027/28 stays. min_gpa/min_ielts NULL. university_id NULL by design (any Austrian university can host); no university_scholarships row. A dedicated verified source was inserted for the OeAD programme page. The programme's sibling lines (FH/university-of-applied-sciences line, Follow-Up Grant, ASEA-UNINET) are different instruments with different target groups and are outside this record.$note$, NULL, 1300, 'EUR', 'month', 'fixed', NULL, 'Monthly grant rate of €1,300 for a research stay of 1-9 months (supplementary grant - own funds required), plus OeAD assistance with accommodation and health insurance arrangements; travel costs subsidy of up to €1,200 for holders from non-European developing countries', 'Not degree funding: the grant supports a visiting research stay only and cannot finance a regular Austrian degree programme; it does not pay tuition (no enrolment as a regular student required).', 'No TOEFL/IELTS certificate required by OeAD, but sufficient subject-area English is expected and the Austrian supervisor must confirm the project can be carried out in English.', $j$["Online application (scholarships/grants portal) with the research stay described in the form's sections (observe the minimum word counts; an upload of a separate proposal is not required)", "Written confirmation of supervision from an Austrian university lecturer on the OeAD template (with date, signature and stamp) - the supervisor cannot also write a recommendation letter", "Letters of recommendation on letterhead, dated, signed and stamped, no older than six months at application", "Diplomas and employment/enrolment confirmations (English or German; otherwise original plus a rough English/German translation, no certified translation needed)", "Scanned valid biometric passport (ID card only for EU applicants); declaration of any generative-AI use in preparing the application"]$j$, NULL, NULL, $json$[{"round": "Stays in the Austrian academic year 2027/28", "opens": "2026-09", "deadline": "2026-12-01", "results": "2027-07", "status": "open"}, {"pattern": "Annual: applications from September to 1 December for research stays (1-9 months) in the following academic year; expert evaluation after the deadline and results around the beginning of July"}]$json$);

